total_box = 0

while True :
    x = int(input("価格を入力してください(0と入力すると終了)："))
    if x == 0:
        if total_box >= 5000 :
            total_box *=0.9
            print(f"合計金額は: {int(total_box)}円です")
        else :
            print(f"合計金額は: {total_box}円です")
        break 
    else :
        total_box += x
